const { Window } = require('happy-dom');
const fs = require('fs');

const window = new Window({ url: 'http://localhost/', settings: { disableJavaScriptFileLoading: true } });
const document = window.document;

document.write(fs.readFileSync('index.html', 'utf8'));
document.close();

console.log('Before eval - todoList exists:', !!document.querySelector('.todo-list'));
console.log('Before eval - todos count:', document.querySelectorAll('.todo-list li').length);

// Patch app.js to add debug logging
let appSource = fs.readFileSync('js/app.js', 'utf8');
console.log('App source length:', appSource.length);
console.log('Contains todoList selector:', appSource.includes("document.querySelector('.todo-list')"));
const searchStr = "var todoList = document.querySelector('.todo-list');";
const replaceStr = `var todoList = document.querySelector('.todo-list');
  console.log('todoList:', todoList);`;
console.log('Search string found:', appSource.includes(searchStr));
appSource = appSource.replace(searchStr, replaceStr);
console.log('After replace, contains new logging:', appSource.includes('todoList:'));
appSource = 'console.log("EVAL START");' + appSource;
appSource = appSource.replace(
  "todoList.addEventListener('change', function (e) {",
  `todoList.addEventListener('change', function (e) {
    console.log('CHANGE event on:', e.target, 'class:', e.target.className);`
);
window.eval(appSource);
document.dispatchEvent(new window.Event('DOMContentLoaded', { bubbles: true }));
window.dispatchEvent(new window.Event('load'));

// Add two todos
const input = document.querySelector('.new-todo');
input.value = 'Buy milk';
input.dispatchEvent(new window.KeyboardEvent('keydown', { key: 'Enter', keyCode: 13, which: 13, bubbles: true }));
input.value = 'Walk dog';
input.dispatchEvent(new window.KeyboardEvent('keydown', { key: 'Enter', keyCode: 13, which: 13, bubbles: true }));

console.log('After adding todos:');
console.log('  todos count:', document.querySelectorAll('.todo-list li').length);
console.log('  toggle-all checked:', document.querySelector('.toggle-all').checked);

// Check both todos
const checkboxes = document.querySelectorAll('.todo-list .toggle');
console.log('Checkbox count:', checkboxes.length);
checkboxes.forEach((cb, i) => {
  console.log(`Checkbox ${i} before: checked =`, cb.checked);
  if (!cb.checked) {
    cb.checked = true;
    console.log(`Checkbox ${i} after set checked:`, cb.checked);
    cb.dispatchEvent(new window.Event('change', { bubbles: true }));
    console.log(`Checkbox ${i} after dispatch change:`, cb.checked);
  }
});

console.log('After checking all:');
console.log('  toggle-all checked:', document.querySelector('.toggle-all').checked);
console.log('  todos completed:', Array.from(document.querySelectorAll('.todo-list li')).every(li => li.classList.contains('completed')));

// Click toggle-all
const toggleAll = document.querySelector('.toggle-all');
console.log('Before click toggle-all: checked =', toggleAll.checked);
toggleAll.click();
console.log('After click toggle-all: checked =', toggleAll.checked);
console.log('  todos completed:', Array.from(document.querySelectorAll('.todo-list li')).every(li => li.classList.contains('completed')));

